<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { usePetStore } from '@/stores/pet'
type Message = { role: 'user' | 'assistant'; text: string; summary?: boolean }
const store = usePetStore(); const context = ref(''); const input = ref(''); const messages = ref<Message[]>([])
onLoad((options) => { context.value = options?.context || '' })
const prompts = computed(() => context.value === 'weight' ? ['豆包最近一个月体重怎么样？', '体重变化需要注意什么？'] : context.value === 'photos' ? ['找去年夏天在阳台的照片', '找豆包小时候的照片'] : ['豆包最近体重怎么样？', '这个月有什么值得注意的变化？', '这个月吃了多少猫粮？'])
function answer(question: string) { if (question.includes('体重')) return '最近 30 天，豆包体重从 5.1 kg 到 5.2 kg，变化很小，整体处在稳定范围内。'; if (question.includes('照片') || question.includes('阳台')) return '我找到了 17 张和「去年夏天 · 阳台」相关的照片，主要集中在 7 月和 8 月。'; if (question.includes('猫粮') || question.includes('吃')) return '这个月平均每天记录主粮 73 g，比上月减少约 4%。体重没有明显变化，可以继续观察。'; return '豆包本月整体状态很稳定。今天还有「剪指甲」提醒，完成后会自动进入成长时间轴。' }
function send(raw = input.value) { const question = raw.trim(); if (!question) return; messages.value.push({ role: 'user', text: question }); input.value = ''; setTimeout(() => messages.value.push({ role: 'assistant', text: answer(question), summary: question.includes('体重') }), 280) }
function back() { uni.navigateBack() }
</script>
<template><view class="screen"><view class="top"><view class="back" @tap="back"><uni-icons type="arrow-left" size="22" color="#1C1C1E" /></view><view><text>FaFa AI</text><text><view />正在了解 {{ store.pet.name }} 的生活</text></view><view class="more"><uni-icons type="more-filled" size="21" color="#1C1C1E" /></view></view><scroll-view scroll-y class="chat" :scroll-into-view="messages.length ? `m-${messages.length - 1}` : ''"><view v-if="!messages.length" class="welcome"><view class="assistant-avatar"><uni-icons type="chat-filled" size="29" color="#FFFFFF" /></view><text class="hello">想知道什么？</text><text class="intro">我会基于豆包的日常记录、照片和成长档案，给你一个清晰的回答。</text><view class="pet-chip"><image :src="store.pet.avatar" mode="aspectFill" /><text>正在陪伴 {{ store.pet.name }}</text></view><text class="label">试着这样问</text><view class="prompt-group"><view v-for="prompt in prompts" :key="prompt" @tap="send(prompt)"><text>{{ prompt }}</text><uni-icons type="arrow-right" size="15" color="#C7C7CC" /></view></view></view><view v-else class="messages"><view v-for="(message, index) in messages" :id="`m-${index}`" :key="`${message.role}${index}`" class="message" :class="message.role"><view v-if="message.role === 'assistant'" class="mini"><uni-icons type="chat-filled" size="14" color="#FFFFFF" /></view><view class="bubble"><text>{{ message.text }}</text><view v-if="message.summary" class="data"><view><text>30 天平均</text><text>5.16 kg</text></view><view><text>变化趋势</text><text>稳定</text></view></view></view></view></view><view class="bottom-space" /></scroll-view><view class="composer"><input v-model="input" confirm-type="send" placeholder="问问关于豆包的任何事" @confirm="send()" /><view :class="{ ready: input.trim() }" @tap="send()"><uni-icons type="paperplane-filled" size="19" :color="input.trim() ? '#FFFFFF' : '#8E8E93'" /></view></view></view></template>
<style scoped lang="scss">
@use '@/styles/tokens.scss' as *;
.screen { display: flex; height: 100vh; flex-direction: column; background: $canvas; }.top { display: flex; height: 132rpx; align-items: flex-end; padding: 0 32rpx 20rpx; }.top > view:first-child, .more { display: flex; width: 64rpx; height: 64rpx; align-items: center; justify-content: center; border-radius: 50%; background: $surface; }.top > view:nth-child(2) { display: flex; flex: 1; flex-direction: column; gap: 5rpx; margin-left: 15rpx; }.top > view:nth-child(2) > text:first-child { color: $ink; font-size: 30rpx; font-weight: 600; }.top > view:nth-child(2) > text:last-child { display: flex; align-items: center; color: $tertiary; font-size: 19rpx; }.top > view:nth-child(2) view { width: 10rpx; height: 10rpx; margin-right: 6rpx; border-radius: 50%; background: $green; }.chat { flex: 1; }.welcome { display: flex; flex-direction: column; align-items: center; padding: 54rpx 40rpx; }.assistant-avatar { display: flex; width: 108rpx; height: 108rpx; align-items: center; justify-content: center; border-radius: 32rpx; background: $blue; box-shadow: 0 10rpx 24rpx rgba(0,122,255,.2); }.hello { margin-top: 25rpx; color: $ink; font-size: 42rpx; font-weight: 700; }.intro { margin-top: 15rpx; color: $secondary; text-align: center; font-size: 24rpx; line-height: 1.6; }.pet-chip { display: flex; align-items: center; gap: 9rpx; margin-top: 22rpx; padding: 7rpx 15rpx 7rpx 7rpx; border-radius: 99rpx; background: $surface; color: $secondary; font-size: 21rpx; }.pet-chip image { width: 36rpx; height: 36rpx; border-radius: 50%; }.label { align-self: flex-start; margin: 48rpx 0 15rpx; color: $secondary; font-size: 24rpx; font-weight: 500; }.prompt-group { width: 100%; overflow: hidden; border-radius: 25rpx; background: $surface; }.prompt-group view { display: flex; min-height: 86rpx; align-items: center; justify-content: space-between; padding: 18rpx 22rpx; border-bottom: 1rpx solid $separator; }.prompt-group view:last-child { border: 0; }.prompt-group text { color: $ink; font-size: 25rpx; }.messages { padding: 30rpx 32rpx; }.message { display: flex; align-items: flex-start; gap: 12rpx; margin-bottom: 22rpx; }.message.user { justify-content: flex-end; }.mini { display: flex; width: 48rpx; height: 48rpx; flex: 0 0 auto; align-items: center; justify-content: center; border-radius: 16rpx; background: $blue; }.bubble { max-width: 78%; padding: 19rpx 22rpx; border-radius: 23rpx; background: $surface; color: $ink; font-size: 26rpx; line-height: 1.6; }.user .bubble { background: $blue; color: #fff; }.data { display: flex; margin-top: 16rpx; padding-top: 16rpx; border-top: 1rpx solid $separator; }.data view { display: flex; width: 50%; flex-direction: column; gap: 5rpx; }.data view + view { padding-left: 13rpx; border-left: 1rpx solid $separator; }.data text:first-child { color: $tertiary; font-size: 18rpx; }.data text:last-child { color: $blue; font-size: 25rpx; font-weight: 600; }.bottom-space { height: 150rpx; }.composer { position: fixed; right: 0; bottom: 0; left: 0; display: flex; align-items: center; gap: 12rpx; padding: 15rpx 28rpx calc(15rpx + env(safe-area-inset-bottom)); border-top: 1rpx solid $separator; background: $surface; }.composer input { height: 72rpx; flex: 1; padding: 0 20rpx; border-radius: 99rpx; background: $surface-secondary; font-size: 25rpx; }.composer > view { display: flex; width: 72rpx; height: 72rpx; align-items: center; justify-content: center; border-radius: 50%; background: #E5E5EA; }.composer > view.ready { background: $blue; }
</style>
